(function(){
  const svg = $('#cone-svg'), out = $('#cone-out');
  const W=760, H=220;
  const CONES = [
    {label:'σ = {0}', rays:[], dualGens:'all of M', ring:'\\mathbb{C}[x^{\\pm 1}, y^{\\pm 1}]', uvar:'T = (\\mathbb{C}^\\times)^2'},
    {label:'σ = ⟨e₁⟩', rays:[[1,0]], dualGens:'⟨e₁*, ±e₂*⟩', ring:'\\mathbb{C}[x, y^{\\pm 1}]', uvar:'\\mathbb{A}^1 \\times \\mathbb{C}^\\times'},
    {label:'σ = ⟨e₁, e₂⟩', rays:[[1,0],[0,1]], dualGens:'⟨e₁*, e₂*⟩', ring:'\\mathbb{C}[x, y]', uvar:'\\mathbb{A}^2'},
    {label:'σ = ⟨2e₁−e₂, e₂⟩', rays:[[2,-1],[0,1]], dualGens:'⟨e₁*, e₁*+2e₂*⟩', ring:'\\mathbb{C}[x, xy, xy^2]', uvar:'A_1 \\text{ singularity (cone over conic)}'},
  ];
  let active = 2;
  const cellW = W/4, cellH = H;
  const scale = 30;

  function render(){
    while(svg.firstChild) svg.removeChild(svg.firstChild);
    CONES.forEach((c, i)=>{
      const cx = i*cellW + cellW/2;
      const cy = cellH/2 + 6;
      // background pane
      svg.appendChild(SVG('rect',{
        x: i*cellW + 6, y: 6, width: cellW-12, height: cellH-12,
        rx: 6, fill: i===active? 'rgba(255,216,102,0.08)' : 'transparent',
        stroke: i===active? 'var(--yellow)' : 'var(--line)', 'stroke-width':1,
        style:'cursor:pointer','data-idx':i
      }));
      // axes
      svg.appendChild(SVG('line',{x1:cx-cellW/2+22,y1:cy,x2:cx+cellW/2-22,y2:cy,stroke:'var(--line)','stroke-width':1}));
      svg.appendChild(SVG('line',{x1:cx,y1:18,x2:cx,y2:cellH-30,stroke:'var(--line)','stroke-width':1}));
      // shade cone (if any)
      if(c.rays.length === 1){
        // halfline starting at 0 — shade a thin strip
        const v = c.rays[0];
        svg.appendChild(SVG('line',{x1:cx,y1:cy,x2:cx+v[0]*scale*2.5,y2:cy-v[1]*scale*2.5,
          stroke:'var(--blue)','stroke-width':3,'stroke-linecap':'round',style:'cursor:pointer','data-idx':i}));
      } else if (c.rays.length === 2){
        const [a, b] = c.rays;
        const far = 3;
        const pts = [
          [cx, cy],
          [cx+a[0]*scale*far, cy-a[1]*scale*far],
          [cx+(a[0]+b[0])*scale*far, cy-(a[1]+b[1])*scale*far],
          [cx+b[0]*scale*far, cy-b[1]*scale*far]
        ];
        svg.appendChild(SVG('polygon',{
          points: pts.map(p=>p.join(',')).join(' '),
          fill:'var(--blue)','fill-opacity':0.22, stroke:'var(--blue)','stroke-width':1.2,style:'cursor:pointer','data-idx':i
        }));
      }
      // tip dot
      svg.appendChild(SVG('circle',{cx:cx,cy:cy,r:3,fill:'var(--ink)','data-idx':i}));
      // label
      const tx = SVG('text',{x:cx,y:cellH-12,'text-anchor':'middle','font-size':12,fill:'var(--ink)','data-idx':i});
      tx.textContent = c.label;
      svg.appendChild(tx);
    });
    const c = CONES[active];
    out.innerHTML = `cone ${c.label}    →    dual ${c.dualGens}\n` +
                    `ring  𝒪(U_σ) = ${c.ring.replace(/\\mathbb\{C\}/g,'ℂ').replace(/\\pm/g,'±')}\n` +
                    `U_σ = ${c.uvar.replace(/\\mathbb\{C\}/g,'ℂ').replace(/\\mathbb\{A\}/g,'𝔸').replace(/\\times/g,'×').replace(/\\text\{([^}]*)\}/g,'$1')}`;
  }

  svg.addEventListener('click', e=>{
    let node = e.target;
    while (node && node !== svg && !(node.getAttribute && node.getAttribute('data-idx'))) node = node.parentNode;
    const idx = node && node.getAttribute && node.getAttribute('data-idx');
    if (idx !== null && idx !== undefined){ active = parseInt(idx, 10); render(); }
  });
  render();
})();

(function(){
  const svg = $('#oc-svg'), out = $('#oc-out');
  const W=760, H=320;
  // left pane: fan of P^2
  const cxL = 180, cyL = 160, scale = 50;
  // right pane: schematic P^2 with the three coordinate lines + 3 fixed points + open torus
  const cxR = 540, cyR = 160;
  // rays of P^2 fan
  const rays = [[1,0], [0,1], [-1,-1]];
  const rayLabels = ['ρ₁ = e₁', 'ρ₂ = e₂', 'ρ₃ = -e₁-e₂'];
  // cones (dim, indices into rays for those that have them)
  const CONES = [
    {key:'zero', dim:0, label:'σ = {0}',          orbit:'open torus T ⊂ ℙ²', dimO:2},
    {key:'r0',   dim:1, label:'ρ₁ (ray e₁)',       orbit:'divisor D_ρ₁ = {x₀ = 0}', dimO:1, ray:0},
    {key:'r1',   dim:1, label:'ρ₂ (ray e₂)',       orbit:'divisor D_ρ₂ = {x₁ = 0}', dimO:1, ray:1},
    {key:'r2',   dim:1, label:'ρ₃ (ray -e₁-e₂)',   orbit:'divisor D_ρ₃ = {x₂ = 0}', dimO:1, ray:2},
    {key:'c01',  dim:2, label:'σ_{12} = ⟨ρ₁, ρ₂⟩', orbit:'fixed point [0:0:1]',     dimO:0, conePair:[0,1]},
    {key:'c12',  dim:2, label:'σ_{23} = ⟨ρ₂, ρ₃⟩', orbit:'fixed point [1:0:0]',     dimO:0, conePair:[1,2]},
    {key:'c20',  dim:2, label:'σ_{13} = ⟨ρ₁, ρ₃⟩', orbit:'fixed point [0:1:0]',     dimO:0, conePair:[0,2]},
  ];
  let active = 'zero';

  function render(){
    while(svg.firstChild) svg.removeChild(svg.firstChild);

    // ---------- left pane: fan
    // pane border
    svg.appendChild(SVG('rect',{x:20,y:20,width:320,height:280,rx:6,fill:'transparent',stroke:'var(--line)'}));
    const tL = SVG('text',{x:cxL,y:36,'text-anchor':'middle','font-size':12,fill:'var(--mute)'});
    tL.textContent = 'Σ ⊂ N_R'; svg.appendChild(tL);
    // shade three maximal cones
    function shade(rayA, rayB, key){
      const a = rays[rayA], b = rays[rayB], far=3.5;
      const pts=[[cxL,cyL],
        [cxL+a[0]*scale*far, cyL-a[1]*scale*far],
        [cxL+(a[0]+b[0])*scale*far/2, cyL-(a[1]+b[1])*scale*far/2],
        [cxL+b[0]*scale*far, cyL-b[1]*scale*far]];
      const isActive = (active===key);
      svg.appendChild(SVG('polygon',{points:pts.map(p=>p.join(',')).join(' '),
        fill:isActive?'var(--yellow)':'var(--blue)','fill-opacity':isActive?0.32:0.14,
        stroke:isActive?'var(--yellow)':'var(--blue)','stroke-width':1,
        style:'cursor:pointer','data-key':key}));
    }
    shade(0,1,'c01'); shade(1,2,'c12'); shade(0,2,'c20');
    // shade open zero cone with a small disk + label
    {
      const isActive = (active==='zero');
      svg.appendChild(SVG('circle',{cx:cxL,cy:cyL,r:11,fill:isActive?'var(--yellow)':'var(--violet)','fill-opacity':isActive?0.8:0.55,
        stroke:isActive?'var(--yellow)':'var(--violet)','stroke-width':1.5,
        style:'cursor:pointer','data-key':'zero'}));
    }
    // draw rays
    rays.forEach((v,i)=>{
      const key = 'r'+i;
      const isActive = (active===key);
      const x2 = cxL + v[0]*scale*3, y2 = cyL - v[1]*scale*3;
      svg.appendChild(SVG('line',{x1:cxL,y1:cyL,x2,y2,
        stroke:isActive?'var(--yellow)':'var(--ink)','stroke-width':isActive?3.2:2,'stroke-linecap':'round',
        style:'cursor:pointer','data-key':key}));
      // dot at lattice generator
      const gx=cxL+v[0]*scale, gy=cyL-v[1]*scale;
      svg.appendChild(SVG('circle',{cx:gx,cy:gy,r:5,fill:isActive?'var(--yellow)':'var(--ink)',
        style:'cursor:pointer','data-key':key}));
      // label
      const lab = SVG('text',{x:cxL+v[0]*scale*1.65, y:cyL-v[1]*scale*1.65+4,'text-anchor':'middle','font-size':11,fill:'var(--mute)'});
      lab.textContent = rayLabels[i];
      svg.appendChild(lab);
    });

    // ---------- right pane: P^2 schematic
    svg.appendChild(SVG('rect',{x:380,y:20,width:360,height:280,rx:6,fill:'transparent',stroke:'var(--line)'}));
    const tR = SVG('text',{x:cxR,y:36,'text-anchor':'middle','font-size':12,fill:'var(--mute)'});
    tR.textContent = 'ℙ² with its three coordinate lines'; svg.appendChild(tR);
    // three vertices of a triangle
    const Pa=[cxR-110, cyR+80], Pb=[cxR+110, cyR+80], Pc=[cxR, cyR-110];
    // vertex order: Pa = [0:0:1], Pb = [0:1:0], Pc = [1:0:0]?
    // We'll just label by which divisor we mean.
    const fixedPts = {
      'c01': {p:[cxR, cyR+82], lbl:'[0:0:1]'},
      'c20': {p:[cxR-110, cyR-30], lbl:'[0:1:0]'},
      'c12': {p:[cxR+110, cyR-30], lbl:'[1:0:0]'}
    };
    // edges of triangle = three coordinate lines
    const edges = [
      {key:'r0', p:[Pb[0], Pb[1]], q:[Pc[0], Pc[1]], lbl:'D_ρ₁'},
      {key:'r1', p:[Pa[0], Pa[1]], q:[Pc[0], Pc[1]], lbl:'D_ρ₂'},
      {key:'r2', p:[Pa[0], Pa[1]], q:[Pb[0], Pb[1]], lbl:'D_ρ₃'},
    ];
    // open torus = interior of triangle
    {
      const isActive = (active==='zero');
      svg.appendChild(SVG('polygon',{points:`${Pa[0]},${Pa[1]} ${Pb[0]},${Pb[1]} ${Pc[0]},${Pc[1]}`,
        fill:isActive?'var(--yellow)':'var(--violet)','fill-opacity':isActive?0.32:0.10,
        stroke:'none'}));
      if(isActive){
        const tt=SVG('text',{x:cxR, y:cyR+15,'text-anchor':'middle','font-size':12,fill:'var(--yellow)','font-weight':600});
        tt.textContent='T (open dense)'; svg.appendChild(tt);
      }
    }
    // edges
    edges.forEach(e=>{
      const isActive = (active===e.key);
      svg.appendChild(SVG('line',{x1:e.p[0],y1:e.p[1],x2:e.q[0],y2:e.q[1],
        stroke:isActive?'var(--yellow)':'var(--blue)','stroke-width':isActive?4:2.2,'stroke-linecap':'round'}));
      // edge label
      const mx=(e.p[0]+e.q[0])/2, my=(e.p[1]+e.q[1])/2;
      const tx = SVG('text',{x:mx + (e.key==='r0'?8:e.key==='r1'?-8:0), y: my + (e.key==='r2'?-6:6),'font-size':11,
        fill:isActive?'var(--yellow)':'var(--blue)'});
      tx.textContent=e.lbl;
      svg.appendChild(tx);
    });
    // fixed points
    Object.entries(fixedPts).forEach(([k, v])=>{
      const isActive = (active===k);
      svg.appendChild(SVG('circle',{cx:v.p[0],cy:v.p[1],r:isActive?7:5,
        fill:isActive?'var(--yellow)':'var(--ink)',stroke:'#fff','stroke-width':1.5}));
      const tx = SVG('text',{x:v.p[0] + (k==='c20'?-14:k==='c12'?14:0), y: v.p[1] + (k==='c01'?16:-12),'font-size':11,
        fill:isActive?'var(--yellow)':'var(--mute)','text-anchor':k==='c01'?'middle':k==='c20'?'end':'start'});
      tx.textContent=v.lbl; svg.appendChild(tx);
    });

    // readout
    const c = CONES.find(c=>c.key===active);
    out.textContent =
      `cone:  ${c.label}   (dim ${c.dim})\n` +
      `orbit: ${c.orbit}   (dim ${c.dimO})\n` +
      `dim O = n - dim σ = 2 - ${c.dim} = ${c.dimO}.   ✓`;
  }

  svg.addEventListener('click', e=>{
    const k = e.target && e.target.getAttribute && e.target.getAttribute('data-key');
    if(k){ active = k; render(); }
  });
  render();
})();

