const svg = $('#ex-svg'), out = $('#ex-out');
const buttons = $$('#w-examples button[data-ex]');
const cx = 380, cy = 165, scale = 50;
const EX = {
  'A2':   {rays:[[1,0],[0,1]],          maxcones:[[0,1]], lbl:'𝔸² = U_σ for σ = ⟨e₁, e₂⟩',
           desc:'Two rays, one maximal cone (the first quadrant). The "boundary" is the two coordinate axes; their intersection is the origin (the fixed point).', n:2},
  'P1':   {rays:[[1,0],[-1,0]],         maxcones:[[0],[1]], lbl:'ℙ¹: two rays ±e in ℝ',
           desc:'Two rays going in opposite directions; two maximal cones (each a ray). Two affine charts 𝔸¹ ∪ 𝔸¹ glued along 𝔾_m. Two fixed points: 0 and ∞.', n:1},
  'P2':   {rays:[[1,0],[0,1],[-1,-1]],  maxcones:[[0,1],[1,2],[0,2]], lbl:'ℙ²: rays e₁, e₂, -e₁-e₂',
           desc:'Three rays summing to zero, three maximal smooth cones. Three coordinate lines (rays) meeting in three fixed points (max cones). The bone-stock projective plane.', n:2},
  'P1xP1':{rays:[[1,0],[0,1],[-1,0],[0,-1]], maxcones:[[0,1],[1,2],[2,3],[3,0]],
           lbl:'ℙ¹×ℙ¹: four rays ±e₁, ±e₂',
           desc:'Product fan: two rays for each ℙ¹ factor, four maximal cones (the four quadrants). Four toric divisors; four fixed points; smooth and projective.', n:2},
  'F2':   {rays:[[1,0],[0,1],[-1,2],[0,-1]], maxcones:[[0,1],[1,2],[2,3],[3,0]],
           lbl:'F₂: tilt one ray of ℙ¹×ℙ¹',
           desc:'The Hirzebruch surface F_n: replace the ray (-e₁) of ℙ¹×ℙ¹ with (-e₁ + n·e₂). For n=2, D_{(0,1)} (the section at infinity) becomes a (-2)-curve while D_{(0,-1)} stays a (+2)-curve. Smooth, projective; not isomorphic to ℙ¹×ℙ¹.', n:2},
  'Bl0':  {rays:[[1,0],[1,1],[0,1]], maxcones:[[0,1],[1,2]],
           lbl:'Bl₀ 𝔸²: subdivide the first quadrant',
           desc:'Star subdivision of ⟨e₁, e₂⟩ inserting the new ray (1,1). The new ray gives the exceptional divisor E (a copy of ℙ¹). E·E = -1: Bl₀ 𝔸² is the smooth blowup of 𝔸² at the origin.', n:2},
};
let active = 'A2';

function render(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  const ex = EX[active];
  // grid + axes
  svg.appendChild(SVG('line',{x1:80,y1:cy,x2:680,y2:cy,stroke:'var(--line)','stroke-width':1}));
  if(ex.n === 2){
    svg.appendChild(SVG('line',{x1:cx,y1:30,x2:cx,y2:300,stroke:'var(--line)','stroke-width':1}));
    // lattice dots
    for(let i=-4;i<=4;i++) for(let j=-2;j<=2;j++){
      svg.appendChild(SVG('circle',{cx:cx+i*scale, cy:cy-j*scale, r:1.4,fill:'var(--mute)','fill-opacity':0.4}));
    }
  } else {
    for(let i=-5;i<=5;i++){
      svg.appendChild(SVG('circle',{cx:cx+i*scale, cy:cy, r:1.6,fill:'var(--mute)','fill-opacity':0.4}));
    }
  }
  // shade max cones
  ex.maxcones.forEach((mc, i)=>{
    const color = ['var(--blue)','var(--green)','var(--pink)','var(--cyan)'][i % 4];
    if(mc.length === 1){
      // 1d max cone: thick segment
      const v = ex.rays[mc[0]];
      svg.appendChild(SVG('line',{x1:cx, y1:cy, x2:cx+v[0]*scale*2.2, y2:cy-v[1]*scale*2.2,
        stroke:color,'stroke-width':6,'stroke-opacity':0.45,'stroke-linecap':'round'}));
    } else {
      const a = ex.rays[mc[0]], b = ex.rays[mc[1]], far = 4;
      const pts=[[cx,cy],
        [cx+a[0]*scale*far, cy-a[1]*scale*far],
        [cx+(a[0]+b[0])*scale*far/2, cy-(a[1]+b[1])*scale*far/2],
        [cx+b[0]*scale*far, cy-b[1]*scale*far]];
      svg.appendChild(SVG('polygon',{points:pts.map(p=>p.join(',')).join(' '),
        fill:color,'fill-opacity':0.18, stroke:color,'stroke-width':1}));
    }
  });
  // rays
  ex.rays.forEach((v,i)=>{
    const x2 = cx + v[0]*scale*2.5, y2 = cy - v[1]*scale*2.5;
    svg.appendChild(SVG('line',{x1:cx,y1:cy,x2,y2,stroke:'var(--ink)','stroke-width':2,'stroke-linecap':'round'}));
    // generator dot
    svg.appendChild(SVG('circle',{cx:cx+v[0]*scale, cy:cy-v[1]*scale, r:5,
      fill:'var(--yellow)',stroke:'#fff','stroke-width':1.5}));
    const tx = SVG('text',{x:cx+v[0]*scale*1.6 + 4*Math.sign(v[0]||0.1), y:cy-v[1]*scale*1.6 + 4,
      'font-size':11,fill:'var(--yellow)','text-anchor': v[0]>0?'start':v[0]<0?'end':'middle'});
    tx.textContent = `(${v[0]},${v[1]})`;
    svg.appendChild(tx);
  });
  // tip
  svg.appendChild(SVG('circle',{cx:cx, cy:cy, r:3.5, fill:'var(--ink)'}));
  const lab = SVG('text',{x:cx, y:38,'text-anchor':'middle','font-size':13,fill:'var(--ink)','font-weight':600});
  lab.textContent = ex.lbl;
  svg.appendChild(lab);
  // readout
  out.textContent = ex.desc;
}

buttons.forEach(b => b.addEventListener('click', ()=>{
  active = b.getAttribute('data-ex');
  buttons.forEach(x => x.classList.toggle('active', x === b));
  render();
}));
render();
